<?php $title='Histórico'; require __DIR__.'/layout.php'; ?><h1>Histórico</h1><p>Registros dos últimos 30 dias.</p><?php if(!$history): ?><section class="card"><p>Ainda não há registros nesse período. <a href="<?= e(url('record')) ?>">Registre uma noite</a> para começar.</p></section><?php else: ?><div class="records"><?php foreach($history as $r): $minutes=(int)((strtotime($r['fim_em'])-strtotime($r['inicio_em']))/60); ?><article class="card"><h2><?= e(date('D, d/m/Y',strtotime($r['inicio_em']))) ?></h2><p>Realizado: <?= e(date('d/m H:i',strtotime($r['inicio_em']))) ?> → <?= e(date('d/m H:i',strtotime($r['fim_em']))) ?></p><p>Duração calculada: <?= e(intdiv($minutes,60)) ?> h <?= e($minutes%60) ?> min</p><?php if($r['qualidade']): ?><p>Qualidade informada: <?= e($r['qualidade']) ?>/5</p><?php endif; ?><?php if($r['observacao']): ?><p><?= e($r['observacao']) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?><?php require __DIR__.'/end.php'; ?>
